record Tensor {
  var shape: [0..*]int;
  var data: [0..*]real;
  var allocator: owned Shared();

  proc init(shape: [] int, allocator: owned Shared() = defaultAllocator()) {
    this.shape = shape;
    this.allocator = allocator;
    this.data = this.allocator.newArray(real, this.numElements());
  }

  proc deinit() {
    this.allocator.deleteArray(this.data);
  }

  proc numElements() {
    var size = 1;
    for i in this.shape do size *= i;
    return size;
  }

  proc fill(value: real) {
    forall i in this.data do i = value;
  }

  proc add(other: Tensor) {
    if this.shape != other.shape then halt("Shape mismatch");
    forall (i,j) in zip(this.data, other.data) do i += j;
  }

  proc matmul(A: Tensor, B: Tensor) {
    if A.shape[1] != B.shape[0] then halt("Matmul shape mismatch");
    var C = new Tensor((A.shape[0], B.shape[1]));
    C.fill(0.0);
    coforall i in 0..#A.shape[0] do
      for j in 0..#B.shape[1] do
        var sum = 0.0;
        for k in 0..#A.shape[1] do
          sum += A.data[i * A.shape[1] + k] * B.data[k * B.shape[1] + j];
        C.data[i * B.shape[1] + j] = sum;
    return C;
  }

  proc norm2() {
    var norm = 0.0;
    for i in this.data do norm += i * i;
    return sqrt(norm);
  }

  proc divScalar(val: real) {
    forall i in this.data do i /= val;
  }
}

