class QuantumSimulator {
  var numQubits: int = 88;
  var shots: int = 128800;
  var state: [0..*(1<<numQubits)-1] complex;
  var rng: new Random();

  proc init() {
    this.state = newArray(complex, 1<<this.numQubits);
    this.state[0] = 1.0 + 0.0i;
  }

  proc applyHadamard(q: int) {
    var stride = 1 << q;
    coforall i in 0..#stride with (+ reduce this.state) {
      for j in 0..#stride {
        var idx0 = i + j;
        var idx1 = idx0 + stride;
        var amp0 = this.state[idx0];
        var amp1 = this.state[idx1];
        this.state[idx0] = (amp0 + amp1) / sqrt(2.0);
        this.state[idx1] = (amp0 - amp1) / sqrt(2.0);
      }
    }
  }

  proc measure() {
    var probs: [0..#this.state.size] real;
    for i in 0..#this.state.size do
      probs[i] = this.state[i].magnitude()**2;
    var randVal = this.rng.rand();
    var cum = 0.0;
    for i in 0..#probs do {
      cum += probs[i];
      if randVal <= cum then return i;
    }
    return 0;
  }

  proc simulateShots() {
    var outcomes: [0..#this.shots] int;
    for i in 0..#this.shots do
      outcomes[i] = this.measure();
    return outcomes;
  }
}

class FMRNLayer {
  var kanCoeffs: [0..*][0..*] real;
  var ssmA: [0..*] real;
  var ssmB: [0..*] real;
  var ssmC: [0..*] real;
  var tgnWeights: [0..*][0..*] real;
  var layerIdx: int;

  proc init(allocator: owned Shared(), dim: int, dState: int, grid: int, nodeFeat: int, timeDim: int) {
    this.kanCoeffs = allocator.newArray2D(real, grid, dim);
    this.ssmA = allocator.newArray(real, dState);
    this.ssmB = allocator.newArray(real, dState);
    this.ssmC = allocator.newArray(real, dState);
    this.tgnWeights = allocator.newArray2D(real, nodeFeat, timeDim);
    this.layerIdx = 0;
  }

  proc deinit(allocator: owned Shared()) {
    allocator.deleteArray2D(this.kanCoeffs);
    allocator.deleteArray(this.ssmA);
    allocator.deleteArray(this.ssmB);
    allocator.deleteArray(this.ssmC);
    allocator.deleteArray2D(this.tgnWeights);
  }
}

class FMRNModel {
  var allocator: owned Shared() = defaultAllocator();
  var config: FMRNConfig;
  var layers: [0..*] owned FMRNLayer;
  var weights: owned Tensor;
  var ssmStates: [0..*] owned Tensor;
  var tgnMemory: [0..*] owned Tensor;
  var quantum: owned QuantumSimulator?;
  var optimizer: owned CelestialZO;

  proc init(config: FMRNConfig) {
    this.config = config;
    this.layers = this.allocator.newArray(FMRNLayer, config.layers);
    for i in 0..#config.layers do
      this.layers[i] = new FMRNLayer(this.allocator, config.dim, config.ssmDState, config.kanGrid, config.tgnNodeFeat, config.tgnTimeDim);
    this.weights = new Tensor((config.layers * config.dim * config.dim,), this.allocator);
    this.ssmStates = this.allocator.newArray(Tensor, config.layers);
    for i in 0..#config.layers do
      this.ssmStates[i] = new Tensor((config.ssmDState,), this.allocator);
    this.tgnMemory = this.allocator.newArray(Tensor, config.ssmDState);
    for i in 0..#config.ssmDState do
      this.tgnMemory[i] = new Tensor((config.tgnNodeFeat,), this.allocator);
    if config.quantumQubits > 0 then
      this.quantum = new QuantumSimulator();
    this.optimizer = new CelestialZO();
  }

  proc deinit() {
    for l in this.layers do l.deinit(this.allocator);
    this.allocator.deleteArray(this.layers);
    this.weights.deinit();
    for s in this.ssmStates do s.deinit();
    this.allocator.deleteArray(this.ssmStates);
    for t in this.tgnMemory do t.deinit();
    this.allocator.deleteArray(this.tgnMemory);
    if this.quantum != nil then delete this.quantum;
    this.optimizer.deinit();
  }

  proc forward(input: [] real): owned Tensor {
    var embeds = this.embed(input);
    for l in 0..#this.config.layers do
      var kanOut = this.kanLayer(embeds, l);
      var ssmOut = this.ssmStep(kanOut, l);
      var tgnOut = this.tgnUpdate(ssmOut, l);
      embeds = tgnOut;
    }
    var logits = new Tensor((input.size, this.config.vocabSize), this.allocator);
    this.weights.matmul(embeds, logits);
    return logits;
  }
}
